def process_numbers(nums):
    from functools import reduce

    def process(num, acc, index):
        if index % 3 == 0:
            return acc + (num ** 2)
        elif index % 4 == 0:
            return acc + (num ** 3)
        else:
            return acc + num

    return reduce(
        lambda acc, idx_num: process(idx_num[1], acc, idx_num[0]),
        enumerate(nums),
        0
    )
