def round_nearest_away_from_zero(x):
    """
    Round to the nearest integer; ties (fractional part exactly 0.5) round away from zero.
    Works for both int and float inputs, returns int.
    """
    if isinstance(x, bool):
        # Avoid treating booleans as numbers
        raise TypeError("Boolean values are not supported.")
    # Use math.copysign to determine sign for away-from-zero on .5
    try:
        import math
        if not isinstance(x, (int, float)):
            # Attempt to convert
            x = float(x)
        if x == 0:
            return 0
        if x > 0:
            return int(math.floor(x + 0.5))
        else:
            return int(math.ceil(x - 0.5))
    except Exception:
        raise ValueError("Input must be a numeric type convertible to float.")

