def any_within_threshold(nums, threshold):
    """
    Checks if any two numbers in the list are within the given threshold distance.

    Args:
        nums (list of int or float): The list of numbers.
        threshold (int or float): The maximum allowed absolute difference.

    Returns:
        bool: True if there exists a pair with distance <= threshold, False otherwise.
    """
    if len(nums) < 2:
        return False

    sorted_nums = sorted(nums)
    return any(
        abs(sorted_nums[i] - sorted_nums[i-1]) <= threshold
        for i in range(1, len(sorted_nums))
    )

