from itertools import count

def first_digit(n: int) -> int:
    n = abs(n)
    while n >= 10:
        n //= 10
    return n

def is_odd(x: int) -> bool:
    return x % 2 == 1

def count_elements_gt_10_with_odd_ends(seq):
    # Functional style: filter, map, and sum with a generator
    return sum(
        1 for x in seq
        if x > 10 and is_odd(first_digit(x)) and is_odd(abs(x) % 10)
    )

# Example usage:
